def GenerateFlagText(bear_sum):
    import base64
    if bear_sum:
        bear_cap = "ZmxhZ3tvbGRfYzBkMy0xcy9kNG5nZXJvdXN9"
        return base64.b64decode(bear_cap).decode('utf-8')
    else:
        return mod(bear_sum)

And renamed original flag function to:
def TileSway(sum):
    key = sum >> 8
    encoded = "\xd0\xc7\xdf\xdb\xd4\xd0\xd4\xdc\xe3\xdb\xd1\xcd\x9f\xb5\xa7\xa7\xa0\xac\xa3\xb4\x88\xaf\xa6\xaa\xbe\xa8\xe3\xa0\xbe\xff\xb1\xbc\xb9"
    plaintext = []
    for i in range(0, len(encoded)):
        plaintext.append(chr(ord(encoded[i]) ^ (key+i)))
    return ''.join(plaintext)

